class driver extends uvm_driver#(transaction);
`uvm_component_utils(driver)
virtual native_if vif;
function new(string name,uvm_component parent); super.new(name,parent); endfunction
function void build_phase(uvm_phase phase);
if(!uvm_config_db#(virtual native_if)::get(this,"","vif",vif)) `uvm_fatal("CFG","missing native interface")
endfunction
task run_phase(uvm_phase phase);
forever begin seq_item_port.get_next_item(req); @(negedge vif.clk); {vif.dmem_rdata_i,vif.imem_rdata_i,vif.rst_n}=req.inputs; @(posedge vif.clk); seq_item_port.item_done(); end
endtask
endclass
class monitor extends uvm_component;
`uvm_component_utils(monitor)
virtual native_if vif;
uvm_analysis_port#(transaction) observed;
int next_id=0;
function new(string name,uvm_component parent); super.new(name,parent); observed=new("observed",this); endfunction
function void build_phase(uvm_phase phase);
if(!uvm_config_db#(virtual native_if)::get(this,"","vif",vif)) `uvm_fatal("CFG","missing native interface")
endfunction
function void sample();
transaction item=transaction::type_id::create("actual");
item.sample_id=next_id++; item.inputs={vif.dmem_rdata_i,vif.imem_rdata_i,vif.rst_n}; item.data={vif.dmem_addr_o,vif.dmem_be_o,vif.dmem_re_o,vif.dmem_wdata_o,vif.dmem_we_o,vif.imem_addr_o}; observed.write(item);
endfunction
task run_phase(uvm_phase phase);
bit initialized=0;
forever begin @(posedge vif.clk); if(initialized) sample(); #1; initialized=1; sample(); end
endtask
endclass
class predictor extends uvm_component;
`uvm_component_utils(predictor)
virtual native_if vif;
uvm_analysis_port#(transaction) expected;
int next_id=0;
function new(string name,uvm_component parent); super.new(name,parent); expected=new("expected",this); endfunction
function void build_phase(uvm_phase phase);
if(!uvm_config_db#(virtual native_if)::get(this,"","vif",vif)) `uvm_fatal("CFG","missing native interface")
endfunction
function void sample();
transaction item=transaction::type_id::create("prediction");
item.sample_id=next_id++; item.inputs={vif.dmem_rdata_i,vif.imem_rdata_i,vif.rst_n}; item.data={vif.expected_dmem_addr_o,vif.expected_dmem_be_o,vif.expected_dmem_re_o,vif.expected_dmem_wdata_o,vif.expected_dmem_we_o,vif.expected_imem_addr_o}; expected.write(item);
endfunction
task run_phase(uvm_phase phase);
bit initialized=0;
forever begin @(posedge vif.clk); if(initialized) sample(); #1; initialized=1; sample(); end
endtask
endclass
class scoreboard extends uvm_component;
`uvm_component_utils(scoreboard)
uvm_analysis_imp_actual#(transaction,scoreboard) actual_export;
uvm_analysis_imp_predicted#(transaction,scoreboard) predicted_export;
transaction actual_pending[int], predicted_pending[int];
int checked=0;
function new(string name,uvm_component parent); super.new(name,parent); actual_export=new("actual_export",this); predicted_export=new("predicted_export",this); endfunction
function bit equal_outputs(logic[102-1:0] actual_value,logic[102-1:0] expected_value);
return actual_value===expected_value && !$isunknown({actual_value,expected_value});
endfunction
function void compare(int identity);
if(actual_pending.exists(identity) && predicted_pending.exists(identity)) begin
checked++;
if(!equal_outputs(actual_pending[identity].data,predicted_pending[identity].data))
`uvm_error("COMPARE",$sformatf("sample=%0d inputs=%h actual=%h expected=%h",identity,actual_pending[identity].inputs,actual_pending[identity].data,predicted_pending[identity].data))
actual_pending.delete(identity); predicted_pending.delete(identity);
end
endfunction
function void write_actual(transaction item); actual_pending[item.sample_id]=item; compare(item.sample_id); endfunction
function void write_predicted(transaction item); predicted_pending[item.sample_id]=item; compare(item.sample_id); endfunction
endclass
class protocol_checker_component extends uvm_subscriber#(transaction);
`uvm_component_utils(protocol_checker_component)
function new(string name,uvm_component parent); super.new(name,parent); endfunction
function void write(transaction item);
if($isunknown(item.data)) `uvm_error("KNOWN","unknown value in observable output")
endfunction
endclass
class coverage extends uvm_subscriber#(transaction);
`uvm_component_utils(coverage)
covergroup observations with function sample(logic[65-1:0] input_bits,logic[102-1:0] output_bits);
option.per_instance=1;
cp_dmem_rdata_i: coverpoint input_bits[33 +: 32] {option.auto_bin_max=16;}
cp_imem_rdata_i: coverpoint input_bits[1 +: 32] {option.auto_bin_max=16;}
cp_rst_n: coverpoint input_bits[0 +: 1] {option.auto_bin_max=16;}
endgroup
function new(string name,uvm_component parent); super.new(name,parent); observations=new(); endfunction
function void write(transaction item); observations.sample(item.inputs,item.data); endfunction
endclass
class environment extends uvm_env;
`uvm_component_utils(environment)
uvm_sequencer#(transaction) sequencer;
driver drv; monitor mon; predictor pred; scoreboard sb; protocol_checker_component protocol_checker; coverage cov;
function new(string name,uvm_component parent); super.new(name,parent); endfunction
function void build_phase(uvm_phase phase);
sequencer=uvm_sequencer#(transaction)::type_id::create("sequencer",this);
drv=driver::type_id::create("drv",this); mon=monitor::type_id::create("mon",this); pred=predictor::type_id::create("pred",this);
sb=scoreboard::type_id::create("sb",this); protocol_checker=protocol_checker_component::type_id::create("protocol_checker",this); cov=coverage::type_id::create("cov",this);
endfunction
function void connect_phase(uvm_phase phase);
drv.seq_item_port.connect(sequencer.seq_item_export); mon.observed.connect(sb.actual_export); pred.expected.connect(sb.predicted_export);
mon.observed.connect(protocol_checker.analysis_export); mon.observed.connect(cov.analysis_export);
endfunction
endclass
class dvbench_test extends uvm_test;
`uvm_component_utils(dvbench_test)
environment env;
virtual native_if vif;
function new(string name="dvbench_test",uvm_component parent=null); super.new(name,parent); endfunction
function void build_phase(uvm_phase phase);
env=environment::type_id::create("env",this);
if(!uvm_config_db#(virtual native_if)::get(this,"","vif",vif)) `uvm_fatal("CFG","missing native interface")
endfunction
task run_phase(uvm_phase phase);
stimulus_sequence sequence_instance;
phase.raise_objection(this); sequence_instance=stimulus_sequence::type_id::create("sequence_instance"); sequence_instance.start(env.sequencer);
repeat(5) @(negedge vif.clk); phase.drop_objection(this);
endtask
function void report_phase(uvm_phase phase);
if(env.sb.checked<4028 || env.sb.actual_pending.num()!=0 || env.sb.predicted_pending.num()!=0) `uvm_error("NONVACUITY","insufficient checks or unpaired observations")
if(uvm_report_server::get_server().get_severity_count(UVM_ERROR)==0 && uvm_report_server::get_server().get_severity_count(UVM_FATAL)==0)
`uvm_info("DVBench_COMPLETED","DVBench_COMPLETED",UVM_NONE)
endfunction
endclass
endpackage
module dvbench_top;
import uvm_pkg::*; import reference_pkg::*;
logic clk=0; always #5 clk=~clk;
native_if bus(clk);
rv32i_single_cycle_core dut(.clk(bus.clk),.dmem_addr_o(bus.dmem_addr_o),.dmem_be_o(bus.dmem_be_o),.dmem_rdata_i(bus.dmem_rdata_i),.dmem_re_o(bus.dmem_re_o),.dmem_wdata_o(bus.dmem_wdata_o),.dmem_we_o(bus.dmem_we_o),.imem_addr_o(bus.imem_addr_o),.imem_rdata_i(bus.imem_rdata_i),.rst_n(bus.rst_n));
